// A classroom on one access point: thirty students fetch the same shell over a slow link.
// Nothing here is generated by the build, so the rules hold for any release: an asset name
// carries its own content hash and can be kept forever, everything else is refreshed.
const SHELL = "ctester-shell-1";
const DATA = "ctester-data-1";

// Published content only. Anything per-student carries an Authorization header and is
// refused below, so a shared browser can never serve one account's answer to another.
const PUBLISHED = /^\/(catalog\.json|exercise\/[^/]+\.json|quiz\/[^/]+\.json|statement\/)/;

self.addEventListener("install", () => self.skipWaiting());

self.addEventListener("activate", (event) => {
  event.waitUntil(
    (async () => {
      const names = await caches.keys();
      await Promise.all(
        names.filter((n) => n !== SHELL && n !== DATA).map((n) => caches.delete(n)),
      );
      await self.clients.claim();
    })(),
  );
});

// ponytail: a count, not a byte budget. Hashed names accumulate one set per release and
// nothing ever evicts them; the Cache API cannot report sizes without reading every entry.
const KEEP_AT_MOST = 80;

async function keep(cache, request, response) {
  if (!response.ok) return response;
  await cache.put(request, response.clone());
  const saved = await cache.keys();
  for (const old of saved.slice(0, saved.length - KEEP_AT_MOST)) await cache.delete(old);
  return response;
}

// Answer from the cache and refresh behind it. Used where a release-old answer is still
// usable: the catalogue, an exercise, a rendered statement.
async function behind(request, name) {
  const cache = await caches.open(name);
  const held = await cache.match(request);
  const fresh = fetch(request)
    .then((response) => keep(cache, request, response))
    .catch(() => held);
  if (!held) return fresh;
  void fresh;
  return held;
}

// The name pins the bytes, so a hit is always right and never needs revalidating.
async function held(request) {
  const cache = await caches.open(SHELL);
  return (await cache.match(request)) ?? keep(cache, request, await fetch(request));
}

// The document names the asset hashes, so it must never be older than them: the cache is
// the offline fallback, not the fast path.
async function ahead(request) {
  const cache = await caches.open(SHELL);
  try {
    return await keep(cache, request, await fetch(request));
  } catch (failure) {
    const saved = await cache.match(request);
    if (saved) return saved;
    throw failure;
  }
}

self.addEventListener("fetch", (event) => {
  const request = event.request;
  if (request.method !== "GET" || request.headers.has("authorization")) return;
  const url = new URL(request.url);

  if (request.mode === "navigate") {
    event.respondWith(ahead(request));
  } else if (url.origin === self.location.origin) {
    if (url.pathname.startsWith("/assets/")) event.respondWith(held(request));
    else if (url.pathname === "/theme.js" || url.pathname === "/favicon.svg") {
      event.respondWith(behind(request, SHELL));
    }
  } else if (PUBLISHED.test(url.pathname)) {
    event.respondWith(behind(request, DATA));
  }
});
